88	Status FabricMemTransferService::InitCommon(const FabricMemTransferServiceInitParam &param, bool enable_aicpu_unfold) {
89	  HIXL_CHK_BOOL_RET_STATUS(param.device_id >= 0, PARAM_INVALID, "device_id must be non-negative.");
90	  HIXL_CHK_BOOL_RET_STATUS(param.max_stream_num > 0, PARAM_INVALID, "max_stream_num must be greater than zero.");
91	  HIXL_CHK_BOOL_RET_STATUS(param.statistic != nullptr && param.local_memory != nullptr, PARAM_INVALID,
92	                           "Invalid fabric mem transfer service initialization parameters.");
93	  const size_t task_stream_num = param.task_stream_num;
94	  HIXL_CHK_BOOL_RET_STATUS(task_stream_num > 0, PARAM_INVALID, "task_stream_num must be greater than zero.");
95	  // An AICPU slot pairs every control stream with a device-only RTSQ worker stream, so it costs
96	  // twice the streams a host slot does and the pool must be sized accordingly.
97	  const size_t streams_per_slot = enable_aicpu_unfold ? (task_stream_num * 2U) : task_stream_num;
98	  HIXL_CHK_BOOL_RET_STATUS(param.max_stream_num >= streams_per_slot, PARAM_INVALID,
99	                           "max_stream_num must leave room for at least one slot's streams.");
100	  device_id_ = param.device_id;
101	  task_stream_num_ = task_stream_num;
102	  max_stream_num_ = param.max_stream_num;
103	  statistic_ = param.statistic;
104	  local_memory_ = param.local_memory;
105	  const size_t max_async_slot_num = param.max_stream_num / streams_per_slot;
106	  HIXL_CHK_STATUS_RET(slot_pool_.Initialize(param.device_id, max_async_slot_num, task_stream_num),
107	                      "Initialize fabric mem slot pool failed.");
108	  HIXL_CHK_STATUS_RET(InitDevConstOne(), "Initialize fabric mem dev_const_one failed.");
109	  FabricMemChannelManagerInitParam manager_param;
110	  manager_param.local_engine = param.local_engine;
111	  manager_param.device_id = param.device_id;
112	  manager_param.auto_connect = param.auto_connect;
113	  manager_param.statistic = param.statistic;
114	  manager_param.slot_pool = &slot_pool_;
115	  manager_param.control_server = param.control_server;
116	  manager_param.aclrt_context = param.aclrt_context;
117	  manager_param.enable_aicpu_unfold = enable_aicpu_unfold;
118	  HIXL_CHK_STATUS_RET(channel_manager_.Initialize(manager_param), "Initialize fabric mem channel manager failed.");
119	  HIXL_LOGI(
120	      "FabricMemTransferService common initialized, device:%d, max_stream:%zu, task_stream:%zu, max_async_slot:%zu, "
121	      "enable_aicpu_unfold:%d.",
122	      device_id_, max_stream_num_, task_stream_num_, max_async_slot_num, static_cast<int32_t>(enable_aicpu_unfold));
123	  return SUCCESS;
124	}
