177	Status FabricMemTransferService::WaitControlStreamsWithTimeout(const AsyncSlot &slot,
178	                                                               const std::chrono::steady_clock::time_point &start,
179	                                                               uint64_t timeout_us) const {
180	  TemporaryRtContext ctx_guard(slot.ctx);
181	  for (const auto &stream : slot.streams) {
182	    const auto cost = GetDurationUs(start, std::chrono::steady_clock::now());
183	    HIXL_CHK_BOOL_RET_STATUS(cost < timeout_us, TIMEOUT, "Fabric mem transfer timeout.");
184	    const uint64_t stream_timeout_ms = (timeout_us - cost) / kMillisToMicros;
185	    HIXL_CHK_BOOL_RET_STATUS(stream_timeout_ms > 0, TIMEOUT, "Fabric mem transfer timeout.");
186	    HIXL_CHK_ACL_RET(aclrtSynchronizeStreamWithTimeout(stream, stream_timeout_ms),
187	                     "Synchronize fabric mem stream failed.");
188	  }
189	  return SUCCESS;
190	}
