192	Status FabricMemTransferService::AppendHostFlagCopies(const AsyncSlot &slot) const {
193	  HIXL_CHK_BOOL_RET_STATUS(slot.streams.size() == slot.host_flags.size(), FAILED,
194	                           "Fabric mem async slot stream/flag size mismatch.");
195	  for (size_t i = 0U; i < slot.streams.size(); ++i) {
196	    HIXL_CHK_ACL_RET(aclrtMemcpyAsync(slot.host_flags[i], kHostFlagSize, dev_const_one_, kHostFlagSize,
197	                                      ACL_MEMCPY_DEVICE_TO_HOST, slot.streams[i]),
198	                     "Fabric mem host flag D2H copy failed.");
199	  }
200	  return SUCCESS;
201	}
202	
203	bool FabricMemTransferService::AllHostFlagsDone(const AsyncSlot &slot) {
204	  for (void *host_flag : slot.host_flags) {
205	    const volatile uint64_t *flag_ptr = static_cast<const volatile uint64_t *>(host_flag);
206	    if (*flag_ptr != kHostFlagDoneValue) {
207	      return false;
208	    }
209	  }
210	  if (slot.host_flags.empty()) {
211	    return false;
212	  }
213	  // Ensure all preceding device-to-host DMA writes (including data transfer results) are
214	  // visible to this thread before the caller observes the completion status.
215	  std::atomic_thread_fence(std::memory_order_acquire);
216	  return true;
217	}
