219	FabricMemTransferService::AsyncStreamQueryResult FabricMemTransferService::QueryAsyncSlotStreams(
220	    const AsyncSlot &slot) {
221	  if (slot.streams.empty()) {
222	    HIXL_LOGE(FAILED, "Fabric mem async slot has no streams.");
223	    return AsyncStreamQueryResult::kFailed;
224	  }
225	  bool all_complete = true;
226	  for (size_t i = 0U; i < slot.streams.size(); ++i) {
227	    aclrtStreamStatus stream_status = ACL_STREAM_STATUS_RESERVED;
228	    const aclError ret = aclrtStreamQuery(slot.streams[i], &stream_status);
229	    if (ret != ACL_SUCCESS) {
230	      HIXL_LOGE(FAILED, "Fabric mem aclrtStreamQuery failed, stream[%zu]:%p, ret:%d.", i,
231	                static_cast<void *>(slot.streams[i]), ret);
232	      return AsyncStreamQueryResult::kFailed;
233	    }
234	    if (stream_status != ACL_STREAM_STATUS_NOT_READY && stream_status != ACL_STREAM_STATUS_COMPLETE) {
235	      HIXL_LOGE(FAILED, "Fabric mem aclrtStreamQuery returned unexpected status:%d, stream[%zu]:%p.",
236	                static_cast<int32_t>(stream_status), i, static_cast<void *>(slot.streams[i]));
237	      return AsyncStreamQueryResult::kFailed;
238	    }
239	    if (stream_status != ACL_STREAM_STATUS_COMPLETE) {
240	      all_complete = false;
241	    }
242	  }
243	  return all_complete ? AsyncStreamQueryResult::kComplete : AsyncStreamQueryResult::kWaiting;
244	}
