255	Status FabricMemTransferService::ResolveTransferAddrs(std::vector<TransferOpDesc> &op_descs,
256	                                                      const FabricMemTransferContext &context) const {
257	  bool need_trans_local_addr = false;
258	  HIXL_CHK_STATUS_RET(NeedTransLocalAddr(op_descs, need_trans_local_addr),
259	                      "Check local fabric mem address type failed.");
260	  for (auto &op : op_descs) {
261	    uintptr_t new_remote_addr = 0;
262	    HIXL_CHK_STATUS_RET(TransOpAddr(op.remote_addr, op.len, context.remote_va_to_old_va, new_remote_addr),
263	                        "Remote fabric mem address is not registered.");
264	    op.remote_addr = new_remote_addr;
265	  }
266	  if (need_trans_local_addr) {
267	    HIXL_CHK_BOOL_RET_STATUS(local_memory_ != nullptr, FAILED, "Fabric mem local memory is not available.");
268	    HIXL_CHK_STATUS_RET(local_memory_->TranslateLocalHostOpAddrs(op_descs),
269	                        "Local host fabric mem address translation failed.");
270	  }
271	  return SUCCESS;
272	}
273	
274	Status FabricMemTransferService::TransOpAddr(uintptr_t old_addr, size_t len,
275	                                             const std::unordered_map<uintptr_t, VaInfo> &new_va_to_old_va,
276	                                             uintptr_t &new_addr) {
277	  for (const auto &item : new_va_to_old_va) {
278	    const auto &info = item.second;
279	    if (IsRangeContained(old_addr, len, info.va_addr, info.len)) {
280	      new_addr = item.first + (old_addr - info.va_addr);
281	      return SUCCESS;
282	    }
283	  }
284	  HIXL_LOGE(PARAM_INVALID, "Fabric mem address:%lu, len:%zu not found in registered segments.", old_addr, len);
285	  return PARAM_INVALID;
286	}
