288	void FabricMemTransferService::UpdateStats(const std::string &channel_id, const std::string &statistic_channel_id,
289	                                           const std::shared_ptr<FabricMemTransferStatisticInfo> &stat_info,
290	                                           uint64_t transfer_cost, uint64_t real_copy_cost, uint64_t transfer_bytes,
291	                                           uint64_t op_desc_count) const {
292	  if (statistic_ == nullptr) {
293	    return;
294	  }
295	  if (stat_info != nullptr) {
296	    statistic_->UpdateCostsDirect(*stat_info, transfer_cost, real_copy_cost, transfer_bytes, op_desc_count);
297	    return;
298	  }
299	  const auto &stat_channel = statistic_channel_id.empty() ? channel_id : statistic_channel_id;
300	  statistic_->UpdateCosts(stat_channel, transfer_cost, real_copy_cost, transfer_bytes, op_desc_count);
301	}
302	
303	Status FabricMemTransferService::NeedTransLocalAddr(const std::vector<TransferOpDesc> &op_descs,
304	                                                    bool &need_trans_local_addr) const {
305	  need_trans_local_addr = false;
306	  if (op_descs.empty() || local_memory_ == nullptr || !local_memory_->HasHostMemory()) {
307	    return SUCCESS;
308	  }
309	  aclrtPtrAttributes attributes{};
310	  HIXL_CHK_ACL_RET(aclrtPointerGetAttributes(reinterpret_cast<void *>(op_descs[0].local_addr), &attributes),
311	                   "Get local pointer attributes failed.");
312	  need_trans_local_addr = (attributes.location.type == ACL_MEM_LOCATION_TYPE_HOST);
313	  return SUCCESS;
314	}
315	}  // namespace hixl
