24	constexpr int64_t kDefaultKeepaliveCheckIntervalMs = 10000;
25	
26	std::vector<FabricMemAicpuPendingRequest> CollectPendingRequests(std::vector<AsyncRecord> &records) {
27	  std::vector<FabricMemAicpuPendingRequest> requests;
28	  requests.reserve(records.size());
29	  for (auto &record : records) {
30	    requests.push_back({&record.slot, &record.aicpu_resource});
31	  }
32	  return requests;
33	}
34	
35	void ReleaseAsyncRecords(std::vector<AsyncRecord> &records, FabricMemSlotPool *slot_pool) {
36	  FabricMemSlotPool::ReleaseRequestResources(CollectPendingRequests(records));
37	  for (auto &record : records) {
38	    slot_pool->Release(record.slot, true);
39	  }
40	}
41	}  // namespace
42	
43	int64_t FabricMemChannelManager::keepalive_check_interval_ms_ = kDefaultKeepaliveCheckIntervalMs;
44	
45	void FabricMemChannelManager::SetKeepaliveCheckIntervalMs(int64_t interval_ms) {
46	  // Lock: none (static interval).
47	  keepalive_check_interval_ms_ = interval_ms > 0 ? interval_ms : kDefaultKeepaliveCheckIntervalMs;
48	}
49	
50	FabricMemChannelManager::~FabricMemChannelManager() {
51	  Finalize();
52	}
53	
54	Status FabricMemChannelManager::Initialize(const FabricMemChannelManagerInitParam &param) {
55	  // Lock: channels_mutex_.
56	  std::lock_guard<std::mutex> lock(channels_mutex_);
57	  HIXL_CHK_BOOL_RET_STATUS(!initialized_, FAILED, "[FabricMemChannelManager] Already initialized.");
58	  HIXL_CHK_BOOL_RET_STATUS(param.statistic != nullptr && param.slot_pool != nullptr, PARAM_INVALID,
59	                           "[FabricMemChannelManager] Invalid initialization parameters.");
60	  local_engine_ = param.local_engine;
61	  device_id_ = param.device_id;
62	  auto_connect_ = param.auto_connect;
63	  statistic_ = param.statistic;
64	  slot_pool_ = param.slot_pool;
65	  control_server_ = param.control_server;
66	  aclrt_context_ = param.aclrt_context;
67	  enable_aicpu_unfold_ = param.enable_aicpu_unfold;
68	  initialized_ = true;
69	  return SUCCESS;
70	}
71	
72	void FabricMemChannelManager::Finalize() noexcept {
73	  // Cleanup must never throw: this runs from this class's destructor and from
74	  // FabricMemTransferService::Finalize()/destructor. The teardown path (vector reserve/emplace in
75	  // AbortAndClearChannelRecords) may throw bad_alloc/length_error, so swallow everything here.
76	  try {
77	    // Lock: none (StopKeepaliveMonitor joins thread; CleanupChannelsLocked takes channels_mutex_).
78	    StopKeepaliveMonitor();
79	    std::lock_guard<std::mutex> lock(channels_mutex_);
80	    CleanupChannelsLocked();
81	    initialized_ = false;
82	  } catch (...) {
83	    HIXL_LOGW("[FabricMemChannelManager] Exception caught during finalize, ignored.");
84	  }
85	}
86	
87	Status FabricMemChannelManager::CreateAndRegisterRemoteMemory(const std::vector<ShareHandleInfo> &share_handles,
88	                                                              const std::string &remote) {
89	  auto remote_memory = MakeUnique<FabricMemRemoteMemory>();
90	  HIXL_CHK_STATUS_RET(remote_memory->Import(share_handles, device_id_),
91	                      "[FabricMemChannelManager] Failed to import remote memory, remote:%s.", remote.c_str());
92	  auto channel = std::make_shared<FabricMemChannel>();
93	  channel->remote_memory = std::move(remote_memory);
94	  statistic_->RegisterChannel(FabricMemStatistic::GetClientStatisticChannelId(remote));
95	  channels_[remote] = std::move(channel);
96	  HIXL_EVENT("[FabricMemChannelManager] Connected, local_engine:%s, remote_engine:%s.", local_engine_.c_str(),
97	             remote.c_str());
98	  return SUCCESS;
99	}
