101	Status FabricMemChannelManager::FetchAndInstallRemote(const std::string &remote, int32_t timeout_in_millis,
102	                                                      Status if_already_connected) {
103	  std::lock_guard<std::mutex> connect_lock(connect_mutex_);
104	  std::vector<ShareHandleInfo> share_handles;
105	  int32_t keepalive_fd = -1;
106	  HIXL_CHK_STATUS_RET(
107	      FabricMemControlClient::Fetch(remote, local_engine_, timeout_in_millis, share_handles, keepalive_fd),
108	      "[FabricMemChannelManager] Failed to fetch share handles from remote:%s.", remote.c_str());
109	  HIXL_DISMISSABLE_GUARD(close_keepalive, ([keepalive_fd]() {
110	                           if (keepalive_fd >= 0) {
111	                             (void)close(keepalive_fd);
112	                           }
113	                         }));
114	  {
115	    std::lock_guard<std::mutex> lock(channels_mutex_);
116	    if (channels_.find(remote) != channels_.end()) {
117	      return if_already_connected;
118	    }
119	    HIXL_CHK_STATUS_RET(CreateAndRegisterRemoteMemory(share_handles, remote),
120	                        "[FabricMemChannelManager] Failed to register remote memory, remote:%s.", remote.c_str());
121	    if (keepalive_fd >= 0) {
122	      channels_[remote]->keepalive_fd = keepalive_fd;
123	    }
124	  }
125	  HIXL_DISMISS_GUARD(close_keepalive);
126	  return SUCCESS;
127	}
