189	void FabricMemChannelManager::AbortAndClearChannelRecords(const std::shared_ptr<FabricMemChannel> &channel) {
190	  channel->disconnecting.store(true, std::memory_order_release);
191	  if (enable_aicpu_unfold_) {
192	    AbortAndClearAicpuChannelRecords(channel);
193	  } else {
194	    AbortAndClearHostChannelRecords(channel);
195	  }
196	}
197	
198	void FabricMemChannelManager::AbortAndClearHostChannelRecords(const std::shared_ptr<FabricMemChannel> &channel) {
199	  // Abort in-flight transfers without waiting. Async records are aborted and
200	  // destroyed here; sync slots are only aborted so the owning transfer thread
201	  // can release them on its failure path.
202	  std::vector<AsyncRecord> async_records;
203	  std::vector<uint64_t> req_ids;
204	  // Mark disconnecting first so new transfers fail fast, then take submit_gate EXCLUSIVE to drain all
205	  // in-flight submits: once acquired, no transfer is mid-submission and every transfer that did submit
206	  // has already registered its slot/record below, so the abort here covers all outstanding streams
207	  // before the caller unmaps the channel memory (abort-before-unmap).
208	  {
209	    std::unique_lock<std::shared_mutex> drain(channel->submit_gate);
210	    std::lock_guard<std::mutex> lock(channel->records_mutex);
211	    req_ids.reserve(channel->async_records.size());
212	    async_records.reserve(channel->async_records.size());
213	    for (auto &record : channel->async_records) {
214	      req_ids.emplace_back(record.first);
215	      async_records.emplace_back(std::move(record.second));
216	    }
217	    channel->async_records.clear();
218	    for (const auto &slot : channel->active_sync_slots) {
219	      (void)FabricMemSlotPool::AbortSlotStreams(slot);
220	    }
221	    channel->active_sync_slots.clear();
222	  }
223	  ReleaseAsyncRecords(async_records, slot_pool_);
224	  for (const auto req_id : req_ids) {
225	    RemoveReqRoute(req_id);
226	  }
227	}
228	
229	void FabricMemChannelManager::AbortAndClearAicpuChannelRecords(const std::shared_ptr<FabricMemChannel> &channel) {
230	  // transfer_mu waits out any sync that still holds the lock through its stream wait; from there on
231	  // disconnect runs exactly the abort the transfer failure paths run.
232	  std::lock_guard<std::mutex> transfer_lock(channel->transfer_mu);
233	  AbortAicpuChannelLocked(channel, nullptr, nullptr);
234	}
235	
236	void FabricMemChannelManager::AbortAicpuChannelLocked(const std::shared_ptr<FabricMemChannel> &channel,
237	                                                      AsyncSlot *pending_slot,
238	                                                      FabricMemAicpuRequestResource *pending_resource) {
239	  // Every pipelined request on this channel shares one bound_slot, and the control stream stops on
240	  // the first failure, so a single failed request cannot be cleaned up in isolation: drain them all,
241	  // then hand the slot and their buffers to the pool's abort flow.
242	  std::vector<AsyncRecord> async_records;
243	  std::vector<uint64_t> req_ids;
244	  AsyncSlot bound_slot;
245	  {
246	    std::lock_guard<std::mutex> lock(channel->records_mutex);
247	    req_ids.reserve(channel->async_records.size());
248	    async_records.reserve(channel->async_records.size());
249	    for (auto &record : channel->async_records) {
250	      req_ids.emplace_back(record.first);
251	      async_records.emplace_back(std::move(record.second));
252	    }
253	    channel->async_records.clear();
254	    bound_slot = channel->bound_slot;
255	    channel->bound_slot = AsyncSlot{};
256	    channel->bound_slot_refs = 0U;
257	  }
258	  std::vector<FabricMemAicpuPendingRequest> requests = CollectPendingRequests(async_records);
259	  if (pending_slot != nullptr || pending_resource != nullptr) {
260	    // A transfer that failed before (or instead of) being registered as an AsyncRecord.
261	    requests.push_back({pending_slot, pending_resource});
262	  }
263	  slot_pool_->AbortSlot(bound_slot, requests);
264	  if (pending_slot != nullptr) {
265	    *pending_slot = AsyncSlot{};
266	  }
267	  for (const auto req_id : req_ids) {
268	    RemoveReqRoute(req_id);
269	  }
270	}
