272	void FabricMemChannelManager::RemoveChannelEntryLocked(const std::string &remote) {
273	  const auto it = channels_.find(remote);
274	  if (it == channels_.end()) {
275	    return;
276	  }
277	  if (it->second != nullptr && it->second->remote_memory != nullptr) {
278	    it->second->remote_memory->Finalize();
279	  }
280	  statistic_->RemoveStatisticChannel(FabricMemStatistic::GetClientStatisticChannelId(remote));
281	  if (it->second != nullptr && it->second->keepalive_fd >= 0) {
282	    (void)close(it->second->keepalive_fd);
283	    it->second->keepalive_fd = -1;
284	  }
285	  channels_.erase(it);
286	}
