288	Status FabricMemChannelManager::DisconnectRemote(const AscendString &remote_engine, int32_t timeout_in_millis,
289	                                                 bool from_auto_cleanup) {
290	  const std::string remote = remote_engine.GetString();
291	  std::shared_ptr<FabricMemChannel> channel;
292	  {
293	    std::lock_guard<std::mutex> lock(channels_mutex_);
294	    HIXL_CHK_BOOL_RET_STATUS(initialized_, FAILED, "[FabricMemChannelManager] Not initialized.");
295	    const auto it = channels_.find(remote);
296	    if (it == channels_.end()) {
297	      HIXL_LOGW("[FabricMemChannelManager] remote engine:%s is not connected, skip disconnect.", remote.c_str());
298	      return NOT_CONNECTED;
299	    }
300	    channel = it->second;
301	  }
302	  AbortAndClearChannelRecords(channel);
303	
304	  int32_t keepalive_fd = -1;
305	  std::string local_engine;
306	  {
307	    std::lock_guard<std::mutex> lock(channels_mutex_);
308	    if (channel->keepalive_fd >= 0) {
309	      keepalive_fd = channel->keepalive_fd;
310	      channel->keepalive_fd = -1;
311	    }
312	    local_engine = local_engine_;
313	  }
314	  if (keepalive_fd >= 0) {
315	    (void)FabricMemControlClient::Disconnect(remote, local_engine, timeout_in_millis, from_auto_cleanup);
316	    (void)close(keepalive_fd);
317	  }
318	
319	  TemporaryRtContext with_context(aclrt_context_);
320	  std::lock_guard<std::mutex> lock(channels_mutex_);
321	  RemoveChannelEntryLocked(remote);
322	  return SUCCESS;
323	}
