325	Status FabricMemChannelManager::Disconnect(const AscendString &remote_engine, int32_t timeout_in_millis) {
326	  // Lock: channels_mutex_ (lookup); channel->records_mutex during abort.
327	  TemporaryRtContext with_context(aclrt_context_);
328	  return DisconnectRemote(remote_engine, timeout_in_millis);
329	}
