331	void FabricMemChannelManager::DisconnectAll() {
332	  // Lock: channels_mutex_ (snapshot, also guards initialized_); per-channel disconnect off-lock during abort.
333	  std::vector<std::string> remotes;
334	  {
335	    std::lock_guard<std::mutex> lock(channels_mutex_);
336	    if (!initialized_) {
337	      return;
338	    }
339	    remotes.reserve(channels_.size());
340	    for (const auto &item : channels_) {
341	      remotes.emplace_back(item.first);
342	    }
343	  }
344	  TemporaryRtContext with_context(aclrt_context_);
345	  for (const auto &remote : remotes) {
346	    const Status ret = DisconnectRemote(AscendString(remote.c_str()), 0);
347	    if (ret != SUCCESS && ret != NOT_CONNECTED) {
348	      HIXL_LOGW(
349	          "[FabricMemChannelManager] DisconnectAll() failed to release remote:%s, ret:%d. Resources may still be held.",
350	          remote.c_str(), static_cast<int32_t>(ret));
351	    }
352	  }
353	}
