384	void FabricMemChannelManager::CleanupChannelsLocked() {
385	  while (!channels_.empty()) {
386	    const auto it = channels_.begin();
387	    const std::string remote = it->first;
388	    auto channel = it->second;
389	    if (channel != nullptr) {
390	      AbortAndClearChannelRecords(channel);
391	    }
392	    RemoveChannelEntryLocked(remote);
393	  }
