396	Status FabricMemChannelManager::StartKeepaliveMonitor() {
397	  // Lock: none.
398	  keepalive_stop_.store(false);
399	  keepalive_monitor_ = std::thread([this]() {
400	    std::unique_lock<std::mutex> lock(keepalive_cv_mutex_);
401	    while (!keepalive_stop_.load()) {
402	      CheckKeepaliveFds();
403	      keepalive_cv_.wait_for(lock, std::chrono::milliseconds(keepalive_check_interval_ms_),
404	                             [this] { return keepalive_stop_.load(); });
405	    }
406	  });
407	  return SUCCESS;
408	}
409	
410	void FabricMemChannelManager::StopKeepaliveMonitor() {
411	  // Lock: none (signals keepalive_cv_; joins thread).
412	  keepalive_stop_.store(true);
413	  keepalive_cv_.notify_all();
414	  if (keepalive_monitor_.joinable()) {
415	    keepalive_monitor_.join();
416	  }
417	}
418	
419	void FabricMemChannelManager::SendOutboundHeartbeats() {
420	  // Snapshot a private dup() of each keepalive fd under channels_mutex_. dup() keeps the underlying
421	  // socket alive (its open file description is reference counted), so even if a concurrent Disconnect
422	  // closes the original fd, the off-lock SendHeartBeat below can never write to a closed (or recycled)
423	  // fd. Sends stay off-lock so a slow peer cannot stall Disconnect or the keepalive monitor.
424	  std::vector<std::pair<std::string, int32_t>> keepalive_copy;
425	  {
426	    std::lock_guard<std::mutex> lock(channels_mutex_);
427	    if (!initialized_) {
428	      return;
429	    }
430	    keepalive_copy.reserve(channels_.size());
431	    for (const auto &item : channels_) {
432	      if (item.second == nullptr || item.second->keepalive_fd < 0) {
433	        continue;
434	      }
435	      const int32_t dup_fd = ::dup(item.second->keepalive_fd);
436	      if (dup_fd < 0) {
437	        HIXL_LOGW("[FabricMemChannelManager] Failed to dup keepalive fd for remote:%s, errno:%d.", item.first.c_str(),
438	                  errno);
439	        continue;
440	      }
441	      keepalive_copy.emplace_back(item.first, dup_fd);
442	    }
443	  }
444	  for (const auto &item : keepalive_copy) {
445	    const Status ret = FabricMemControlClient::SendHeartBeat(item.second);
446	    (void)close(item.second);
447	    if (ret == SUCCESS) {
448	      continue;
449	    }
450	    HIXL_LOGW("[FabricMemChannelManager] Outbound heartbeat failed for remote:%s, ret:%u.", item.first.c_str(),
451	              static_cast<uint32_t>(ret));
452	    if (auto_connect_) {
453	      DisconnectDeadRemote(item.first);
454	    }
455	  }
456	}
457	
458	void FabricMemChannelManager::CheckKeepaliveFds() {
459	  {
460	    std::lock_guard<std::mutex> lock(channels_mutex_);
461	    if (!initialized_) {
462	      return;
463	    }
464	  }
465	  SendOutboundHeartbeats();
466	  if (auto_connect_ && control_server_ != nullptr) {
467	    control_server_->CheckClientHeartbeatTimeouts();
468	  }
469	}
470	
471	void FabricMemChannelManager::DisconnectDeadRemote(const std::string &remote) {
472	  {
473	    std::lock_guard<std::mutex> lock(channels_mutex_);
474	    if (!initialized_) {
475	      return;
476	    }
477	    if (channels_.find(remote) == channels_.end()) {
478	      return;
479	    }
480	  }
481	  TemporaryRtContext with_context(aclrt_context_);
482	  const Status ret = DisconnectRemote(AscendString(remote.c_str()), 0, true);
483	  if (ret == SUCCESS) {
484	    HIXL_EVENT("[FabricMemChannelManager] Auto-disconnected dead remote:%s due to keepalive failure.", remote.c_str());
485	  } else if (ret != NOT_CONNECTED) {
486	    HIXL_EVENT("[FabricMemChannelManager] Failed to auto-disconnect dead remote:%s, ret:%u.", remote.c_str(),
487	               static_cast<uint32_t>(ret));
488	  }
489	}
