101	  void AddReqRoute(uint64_t req_id, const std::shared_ptr<FabricMemChannel> &channel);
102	  Status FindChannelByReq(uint64_t req_id, std::shared_ptr<FabricMemChannel> &channel) const;
103	  void RemoveReqRoute(uint64_t req_id);
