106	  Status FetchAndInstallRemote(const std::string &remote, int32_t timeout_in_millis, Status if_already_connected);
107	  Status CreateAndRegisterRemoteMemory(const std::vector<ShareHandleInfo> &share_handles, const std::string &remote);
108	  Status DisconnectRemote(const AscendString &remote_engine, int32_t timeout_in_millis, bool from_auto_cleanup = false);
109	  void AbortAndClearChannelRecords(const std::shared_ptr<FabricMemChannel> &channel);
