33	void FabricMemHostTransferService::UnregisterSyncSlot(const std::shared_ptr<FabricMemChannel> &channel,
34	                                                      const AsyncSlot &slot) {
35	  std::lock_guard<std::mutex> lock(channel->records_mutex);
36	  for (auto it = channel->active_sync_slots.begin(); it != channel->active_sync_slots.end(); ++it) {
37	    if (it->ctx == slot.ctx) {
38	      (void)channel->active_sync_slots.erase(it);
39	      return;
40	    }
41	  }
