44	Status FabricMemHostTransferService::IssueSyncCopy(const std::shared_ptr<FabricMemChannel> &channel,
45	                                                   const AsyncSlot &slot, const FabricMemTransferContext &context,
46	                                                   std::vector<TransferOpDesc> &op_descs,
47	                                                   TransferInvocation &invocation) const {
48	  TemporaryRtContext ctx_guard(slot.ctx);
49	  // Cheap lock-free reject so a disconnecting channel fails fast with NOT_CONNECTED before any work;
50	  // the authoritative re-check under submit_gate below closes the race with a concurrent disconnect.
51	  HIXL_CHK_BOOL_RET_STATUS(!channel->disconnecting.load(std::memory_order_acquire), NOT_CONNECTED,
52	                           "Fabric mem channel:%s is disconnecting.", context.channel_id.c_str());
53	  // Resolve addresses before locking: it only reads the context's private VA snapshot and the local op
54	  // addrs (plus an aclrtPointerGetAttributes query), touching no shared channel state.
55	  HIXL_CHK_STATUS_RET(ResolveTransferAddrs(op_descs, context), "Resolve fabric mem addresses failed.");
56	  // Submit under a SHARED lock so concurrent transfers on the same channel issue copies in parallel; the
57	  // slot is registered (under records_mutex) before submitting and before releasing the shared lock, so a
58	  // concurrent disconnect (which takes submit_gate EXCLUSIVE) sees it and aborts the streams before unmap.
59	  std::shared_lock<std::shared_mutex> submit_lock(channel->submit_gate);
60	  HIXL_CHK_BOOL_RET_STATUS(!channel->disconnecting.load(std::memory_order_acquire), NOT_CONNECTED,
61	                           "Fabric mem channel:%s is disconnecting.", context.channel_id.c_str());
62	  {
63	    std::lock_guard<std::mutex> reg(channel->records_mutex);
64	    channel->active_sync_slots.emplace_back(slot);
65	  }
66	  invocation.real_copy_start = std::chrono::steady_clock::now();
67	  HIXL_CHK_STATUS_RET(ProcessCopyWithAsync(slot, invocation.operation, op_descs), "Fabric mem copy failed.");
68	  return SUCCESS;
69	}
70	
71	Status FabricMemHostTransferService::TransferSync(const std::string &remote_engine, TransferOp operation,
72	                                                  const std::vector<TransferOpDesc> &op_descs,
73	                                                  int32_t timeout_in_millis) {
74	  HIXL_CHK_BOOL_RET_STATUS(timeout_in_millis >= 0, PARAM_INVALID,
75	                           "Fabric mem transfer timeout must be non-negative, got:%d.", timeout_in_millis);
76	  const auto start = std::chrono::steady_clock::now();
77	  const uint64_t timeout_us = static_cast<uint64_t>(timeout_in_millis) * kMillisToMicros;
78	  std::shared_ptr<FabricMemChannel> channel;
79	  FabricMemTransferContext context;
80	  HIXL_CHK_STATUS_RET(PrepareChannelTransfer(remote_engine, channel, context), "Prepare fabric mem transfer failed.");
81	  AsyncSlot slot;
82	  HIXL_CHK_STATUS_RET(slot_pool_.AcquireWithTimeout(slot, timeout_us), "Failed to acquire fabric mem transfer slot.");
83	  HIXL_DISMISSABLE_GUARD(fail_guard, ([this, &channel, &slot]() {
84	                           UnregisterSyncSlot(channel, slot);
85	                           slot_pool_.Release(slot, true);
86	                         }));
87	  auto op_descs_copy = op_descs;
88	  TransferInvocation invocation;
89	  invocation.operation = operation;
90	  HIXL_CHK_STATUS_RET(IssueSyncCopy(channel, slot, context, op_descs_copy, invocation), "Fabric mem sync copy failed.");
91	  HIXL_CHK_STATUS_RET(WaitControlStreamsWithTimeout(slot, start, timeout_us), "Wait fabric mem sync streams failed.");
92	  const auto real_copy_cost = GetDurationUs(invocation.real_copy_start, std::chrono::steady_clock::now());
93	  HIXL_DISMISS_GUARD(fail_guard);
94	  UnregisterSyncSlot(channel, slot);
95	  slot_pool_.Release(slot, false);
96	  const auto transfer_cost = GetDurationUs(start, std::chrono::steady_clock::now());
97	  UpdateStats(context.channel_id, context.statistic_channel_id, context.stat_info, transfer_cost, real_copy_cost,
98	              GetTransferBytes(op_descs_copy), static_cast<uint64_t>(op_descs_copy.size()));
99	  HIXL_LOGI("Fabric mem transfer cost:%lu us, real copy:%lu us, channel:%s.", transfer_cost, real_copy_cost,
100	            context.channel_id.c_str());
101	  return SUCCESS;
102	}
