104	Status FabricMemHostTransferService::IssueAsyncCopyAndRegister(const std::shared_ptr<FabricMemChannel> &channel,
105	                                                               AsyncSlot &slot, const FabricMemTransferContext &context,
106	                                                               std::vector<TransferOpDesc> &op_descs,
107	                                                               TransferInvocation &invocation) {
108	  TemporaryRtContext ctx_guard(slot.ctx);
109	  // Cheap lock-free reject so a disconnecting channel fails fast with NOT_CONNECTED before any work;
110	  // the authoritative re-check under submit_gate below closes the race with a concurrent disconnect.
111	  HIXL_CHK_BOOL_RET_STATUS(!channel->disconnecting.load(std::memory_order_acquire), NOT_CONNECTED,
112	                           "Fabric mem channel:%s is disconnecting.", context.channel_id.c_str());
113	  // Resolve addresses before locking (see IssueSyncCopy).
114	  HIXL_CHK_STATUS_RET(ResolveTransferAddrs(op_descs, context), "Resolve fabric mem addresses failed.");
115	  // Submit under a SHARED lock so concurrent transfers run in parallel. The record is registered (under
116	  // records_mutex) AFTER submitting but BEFORE releasing the shared lock, so a concurrent disconnect
117	  // (submit_gate EXCLUSIVE) is guaranteed to observe it and abort the slot's streams before unmap.
118	  std::shared_lock<std::shared_mutex> submit_lock(channel->submit_gate);
119	  HIXL_CHK_BOOL_RET_STATUS(!channel->disconnecting.load(std::memory_order_acquire), NOT_CONNECTED,
120	                           "Fabric mem channel:%s is disconnecting.", context.channel_id.c_str());
121	  invocation.real_copy_start = std::chrono::steady_clock::now();
122	  HIXL_CHK_STATUS_RET(ProcessCopyWithAsync(slot, invocation.operation, op_descs), "Fabric mem async copy failed.");
123	  HIXL_CHK_STATUS_RET(AppendHostFlagCopies(slot), "Failed to append fabric mem host flag copies.");
124	  AsyncRecord record;
125	  record.slot = std::move(slot);
126	  record.transfer_start = invocation.transfer_start;
127	  record.real_copy_start = invocation.real_copy_start;
128	  record.transfer_bytes = GetTransferBytes(op_descs);
129	  record.op_desc_count = static_cast<uint64_t>(op_descs.size());
130	  record.channel_id = context.channel_id;
131	  record.statistic_channel_id = context.statistic_channel_id;
132	  record.stat_info = context.stat_info;
133	  record.op_type = invocation.operation;
134	  record.prof_start_time = invocation.prof_start_time;
135	  {
136	    std::lock_guard<std::mutex> reg(channel->records_mutex);
137	    channel->async_records[invocation.req_id] = std::move(record);
138	  }
139	  channel_manager_.AddReqRoute(invocation.req_id, channel);
140	  return SUCCESS;
141	}
