143	Status FabricMemHostTransferService::TransferAsync(const std::string &remote_engine, TransferOp operation,
144	                                                   const std::vector<TransferOpDesc> &op_descs, TransferReq &req) {
145	  const uint64_t req_id = next_req_id_.fetch_add(1U, std::memory_order_relaxed);
146	  req = reinterpret_cast<TransferReq>(static_cast<uintptr_t>(req_id));
147	  const uint64_t prof_start_time = HixlProfilingReporter::GetSysCycleTime();
148	  const auto start = std::chrono::steady_clock::now();
149	  std::shared_ptr<FabricMemChannel> channel;
150	  FabricMemTransferContext context;
151	  HIXL_CHK_STATUS_RET(PrepareChannelTransfer(remote_engine, channel, context), "Prepare fabric mem transfer failed.");
152	  AsyncSlot slot;
153	  HIXL_CHK_STATUS_RET(slot_pool_.AcquireAsync(slot), "Failed to acquire fabric mem async slot.");
154	  HIXL_DISMISSABLE_GUARD(fail_guard, ([this, &slot]() { slot_pool_.Release(slot, true); }));
155	  auto op_descs_copy = op_descs;
156	  TransferInvocation invocation;
157	  invocation.operation = operation;
158	  invocation.req_id = req_id;
159	  invocation.prof_start_time = prof_start_time;
160	  invocation.transfer_start = start;
161	  invocation.real_copy_start = std::chrono::steady_clock::now();
162	  HIXL_CHK_STATUS_RET(IssueAsyncCopyAndRegister(channel, slot, context, op_descs_copy, invocation),
163	                      "Fabric mem async submit failed.");
164	  HIXL_DISMISS_GUARD(fail_guard);
165	  HIXL_LOGI("Fabric mem async transfer submitted, channel:%s, req:%lu, cost:%lu us.", context.channel_id.c_str(),
166	            req_id, GetDurationUs(start, std::chrono::steady_clock::now()));
167	  return SUCCESS;
168	}
169	
170	Status FabricMemHostTransferService::GetTransferStatus(const TransferReq &req, TransferStatus &status,
171	                                                       AsyncTransferPollInfo *info) {
172	  const uint64_t req_id = reinterpret_cast<uintptr_t>(req);
173	  std::shared_ptr<FabricMemChannel> channel;
174	  // Unknown req / route already removed (completed) / route cleared by Disconnect abort -> PARAM_INVALID.
175	  // FindChannelByReq returns FAILED internally; map to PARAM_INVALID for the caller-facing contract.
176	  HIXL_CHK_BOOL_RET_STATUS(channel_manager_.FindChannelByReq(req_id, channel) == SUCCESS, PARAM_INVALID,
177	                           "Fabric mem request:%lu not found.", req_id);
178	
179	  AsyncRecord async_record;
180	  bool host_flags_done = false;
181	  AsyncStreamQueryResult query_result = AsyncStreamQueryResult::kFailed;
182	  {
183	    // Single critical section: locate the record once, then decide completion via the cheap host-flag
184	    // poll first and fall back to aclrtStreamQuery (with its rt-context setup) only when the flags are
185	    // not yet set. Holding records_mutex across the lookup and extraction stops a concurrent Disconnect
186	    // (AbortAndClearChannelRecords) from moving the slot out and destroying its streams in between; the
187	    // blocking SynchronizeAsyncSlotStreams below runs only after the record is locally owned.
188	    std::lock_guard<std::mutex> lock(channel->records_mutex);
189	    const auto it = channel->async_records.find(req_id);
190	    HIXL_CHK_BOOL_RET_STATUS(it != channel->async_records.end(), PARAM_INVALID, "Fabric mem request:%lu not found.",
191	                             req_id);
192	    host_flags_done = AllHostFlagsDone(it->second.slot);
193	    if (!host_flags_done) {
194	      TemporaryRtContext ctx_guard(it->second.slot.ctx);
195	      query_result = QueryAsyncSlotStreams(it->second.slot);
196	      if (query_result == AsyncStreamQueryResult::kWaiting) {
197	        status = TransferStatus::WAITING;
198	        return SUCCESS;
199	      }
200	    }
201	    async_record = std::move(it->second);
202	    (void)channel->async_records.erase(it);
203	  }
204	
205	  Status ret;
206	  if (host_flags_done) {
207	    // Host completion flags are already set (acquire fence in AllHostFlagsDone), so the copy results are
208	    // guaranteed visible and the stream sync can be skipped.
209	    ret = CompleteAsyncTransferAndUpdateStats(req_id, async_record, status);
210	  } else if (query_result == AsyncStreamQueryResult::kComplete &&
211	             SynchronizeAsyncSlotStreams(async_record.slot) == SUCCESS) {
212	    ret = CompleteAsyncTransferAndUpdateStats(req_id, async_record, status);
213	  } else {
214	    ret = HandleAsyncStreamQueryFailure(req_id, async_record, status);
215	  }
216	  FillPollInfo(async_record, info);
217	  channel_manager_.RemoveReqRoute(req_id);
218	  return ret;
219	}
220	
221	Status FabricMemHostTransferService::HandleAsyncStreamQueryFailure(uint64_t req_id, AsyncRecord &async_record,
222	                                                                   TransferStatus &status) {
223	  slot_pool_.Release(async_record.slot, true);
224	  status = TransferStatus::FAILED;
225	  HIXL_LOGE(FAILED, "Fabric mem async transfer failed on stream query, req:%lu.", req_id);
226	  return SUCCESS;
227	}
228	
229	Status FabricMemHostTransferService::SynchronizeAsyncSlotStreams(const AsyncSlot &slot) {
230	  TemporaryRtContext ctx_guard(slot.ctx);
231	  for (const auto &stream : slot.streams) {
232	    HIXL_CHK_ACL_RET(aclrtSynchronizeStream(stream), "Synchronize fabric mem async stream failed.");
233	  }
234	  return SUCCESS;
235	}
236	
237	Status FabricMemHostTransferService::CompleteAsyncTransferAndUpdateStats(uint64_t req_id, AsyncRecord &async_record,
238	                                                                         TransferStatus &status) {
239	  slot_pool_.Release(async_record.slot, false);
240	  const auto end = std::chrono::steady_clock::now();
241	  const auto real_copy_cost = GetDurationUs(async_record.real_copy_start, end);
242	  const auto transfer_cost = GetDurationUs(async_record.transfer_start, end);
243	  UpdateStats(async_record.channel_id, async_record.statistic_channel_id, async_record.stat_info, transfer_cost,
244	              real_copy_cost, async_record.transfer_bytes, async_record.op_desc_count);
245	  status = TransferStatus::COMPLETED;
246	  HIXL_LOGI("Fabric mem async transfer completed, channel:%s, req:%lu, cost:%lu us, real copy:%lu us.",
247	            async_record.channel_id.c_str(), req_id, transfer_cost, real_copy_cost);
248	  return SUCCESS;
249	}
250	
251	void FabricMemHostTransferService::CleanupAsyncTransfer(const TransferReq &req) {
252	  const uint64_t req_id = reinterpret_cast<uintptr_t>(req);
253	  std::shared_ptr<FabricMemChannel> channel;
254	  if (channel_manager_.FindChannelByReq(req_id, channel) != SUCCESS) {
255	    return;
256	  }
257	  AsyncSlot slot;
258	  bool found = false;
259	  {
260	    std::lock_guard<std::mutex> lock(channel->records_mutex);
261	    const auto it = channel->async_records.find(req_id);
262	    if (it != channel->async_records.end()) {
263	      slot = std::move(it->second.slot);
264	      (void)channel->async_records.erase(it);
265	      found = true;
266	    }
267	  }
268	  if (found) {
269	    slot_pool_.Release(slot, true);
270	  }
271	  channel_manager_.RemoveReqRoute(req_id);
272	}
273	
274	Status FabricMemHostTransferService::ProcessCopyWithAsync(const AsyncSlot &slot, TransferOp operation,
275	                                                          const std::vector<TransferOpDesc> &op_descs) {
276	  HIXL_CHK_BOOL_RET_STATUS(!slot.streams.empty(), PARAM_INVALID, "Fabric mem copy streams cannot be empty.");
277	  const size_t stream_count = slot.streams.size();
278	  size_t stream_idx = 0U;
279	  for (const auto &op : op_descs) {
280	    auto &stream = slot.streams[stream_idx];
281	    if (++stream_idx >= stream_count) {
282	      stream_idx = 0U;
283	    }
284	    if (operation == TransferOp::WRITE) {
285	      HIXL_CHK_ACL_RET(
286	          aclrtMemcpyAsync(reinterpret_cast<void *>(op.remote_addr), op.len, reinterpret_cast<void *>(op.local_addr),
287	                           op.len, ACL_MEMCPY_DEVICE_TO_DEVICE, stream),
288	          "Fabric mem write copy failed.");
289	      continue;
290	    }
291	    HIXL_CHK_BOOL_RET_STATUS(operation == TransferOp::READ, PARAM_INVALID, "Invalid fabric mem transfer operation.");
292	    HIXL_CHK_ACL_RET(
293	        aclrtMemcpyAsync(reinterpret_cast<void *>(op.local_addr), op.len, reinterpret_cast<void *>(op.remote_addr),
294	                         op.len, ACL_MEMCPY_DEVICE_TO_DEVICE, stream),
295	        "Fabric mem read copy failed.");
296	  }
297	  return SUCCESS;
298	}
299	}  // namespace hixl
