33	Status FabricMemAicpuTransferService::Initialize(const FabricMemTransferServiceInitParam &param) {
34	  HIXL_CHK_BOOL_RET_STATUS(param.task_stream_num == 1U, PARAM_INVALID,
35	                           "enable_aicpu_unfold requires task_stream_num=1, got %zu.", param.task_stream_num);
36	  HIXL_DISMISSABLE_GUARD(fail_guard, ([this]() { Finalize(); }));
37	  const Status dispatcher_status = aicpu_dispatcher_.Initialize(param.device_id);
38	  if (dispatcher_status != SUCCESS) {
39	    HIXL_LOGE(UNSUPPORTED, "FabricMem AICPU unfold requested but unavailable on device:%d.", param.device_id);
40	    return UNSUPPORTED;
41	  }
42	  HIXL_CHK_STATUS_RET(InitCommon(param, true), "Initialize fabric mem AICPU transfer service common failed.");
43	  slot_pool_.SetAicpuDispatcher(&aicpu_dispatcher_);
44	  HIXL_DISMISS_GUARD(fail_guard);
45	  return SUCCESS;
46	}
