48	void FabricMemAicpuTransferService::Finalize() {
49	  // Base Finalize aborts the remaining channels and slots, which still needs the dispatcher.
50	  FabricMemTransferService::Finalize();
51	  slot_pool_.SetAicpuDispatcher(nullptr);
52	  aicpu_dispatcher_.Finalize();
53	}
