55	Status FabricMemAicpuTransferService::AllocateTransferHostFlags(AsyncSlot &slot) {
56	  HIXL_CHK_BOOL_RET_STATUS(!slot.streams.empty(), PARAM_INVALID, "Fabric mem copy streams cannot be empty.");
57	  // Drop any borrowed pool-flag view before installing per-transfer flags (hixl_cs style).
58	  slot.host_flags.clear();
59	  slot.owns_host_flags = false;
60	  std::vector<void *> flags;
61	  flags.reserve(slot.streams.size());
62	  HIXL_DISMISSABLE_GUARD(flag_guard, ([&flags]() {
63	                           for (void *host_flag : flags) {
64	                             if (host_flag != nullptr) {
65	                               (void)aclrtFreeHost(host_flag);
66	                             }
67	                           }
68	                           flags.clear();
69	                         }));
70	  for (size_t i = 0U; i < slot.streams.size(); ++i) {
71	    void *host_flag = nullptr;
72	    HIXL_CHK_ACL_RET(aclrtMallocHost(&host_flag, kHostFlagSize), "Allocate fabric mem transfer host flag failed.");
73	    *static_cast<uint64_t *>(host_flag) = kHostFlagInitValue;
74	    flags.emplace_back(host_flag);
75	  }
76	  slot.host_flags = std::move(flags);
77	  slot.owns_host_flags = true;
78	  HIXL_DISMISS_GUARD(flag_guard);
79	  return SUCCESS;
80	}
