82	Status FabricMemAicpuTransferService::AcquireBoundSlotLocked(const std::shared_ptr<FabricMemChannel> &channel,
83	                                                             AsyncSlot &slot, uint64_t timeout_us, bool async_acquire) {
84	  HIXL_CHK_BOOL_RET_STATUS(!channel->disconnecting.load(std::memory_order_acquire), NOT_CONNECTED,
85	                           "Fabric mem channel is disconnecting.");
86	  if (channel->bound_slot_refs > 0U) {
87	    // Reuse the channel's active slot like hixl_cs AcquireSharedSlot.
88	    HIXL_CHK_BOOL_RET_STATUS(channel->bound_slot.ctx != nullptr, FAILED,
89	                             "Fabric mem AICPU bound slot missing with non-zero refs.");
90	    slot = channel->bound_slot;
91	    ++channel->bound_slot_refs;
92	    return SUCCESS;
93	  }
94	
95	  Status acquire_status = SUCCESS;
96	  if (async_acquire) {
97	    acquire_status = slot_pool_.AcquireAsync(slot);
98	  } else {
99	    acquire_status = slot_pool_.AcquireWithTimeout(slot, timeout_us);
100	  }
101	  HIXL_CHK_STATUS_RET(acquire_status, "Failed to acquire fabric mem AICPU transfer slot.");
102	  // Slot is occupied; abort it if worker stream / notify / transfer-context setup fails before binding.
103	  HIXL_DISMISSABLE_GUARD(slot_guard, ([this, &slot]() { slot_pool_.AbortSlot(slot, {}); }));
104	  HIXL_CHK_STATUS_RET(slot_pool_.EnsureAicpuRtsqStreams(slot), "Create FabricMem AICPU RTSQ worker streams failed.");
105	  slot.has_aicpu_unfold = true;
106	  HIXL_CHK_STATUS_RET(aicpu_dispatcher_.AddTransferContext(slot), "Register FabricMem AICPU transfer context failed.");
107	  channel->bound_slot = slot;
108	  channel->bound_slot_refs = 1U;
109	  HIXL_DISMISS_GUARD(slot_guard);
110	  return SUCCESS;
111	}
