113	void FabricMemAicpuTransferService::ReleaseBoundSlotLocked(const std::shared_ptr<FabricMemChannel> &channel,
114	                                                           AsyncSlot &slot) {
115	  // Success path only: the last owner returns the intact slot to the pool for reuse. Anything that
116	  // failed goes through AbortAicpuChannelLocked instead, which destroys the slot.
117	  FabricMemSlotPool::DestroyOwnedHostFlags(slot);
118	  slot = AsyncSlot{};
119	  if (channel->bound_slot_refs == 0U) {
120	    return;
121	  }
122	  --channel->bound_slot_refs;
123	  if (channel->bound_slot_refs > 0U) {
124	    return;
125	  }
126	  AsyncSlot pool_slot = channel->bound_slot;
127	  channel->bound_slot = AsyncSlot{};
128	  slot_pool_.Release(pool_slot, false);
129	}
