131	void FabricMemAicpuTransferService::CleanupFailedTransferLocked(const std::shared_ptr<FabricMemChannel> &channel,
132	                                                                AsyncSlot &slot,
133	                                                                FabricMemAicpuRequestResource &aicpu_resource) {
134	  // An allocated resource means Submit got far enough to enqueue a kernel that reads it, so the
135	  // channel's shared control stream is no longer trustworthy and every pipelined sibling dies with
136	  // it: run the full abort. Without one, nothing reached the device and the channel stays usable.
137	  if (aicpu_resource.descriptor_buffer == nullptr && aicpu_resource.status_buffer == nullptr) {
138	    ReleaseBoundSlotLocked(channel, slot);
139	    return;
140	  }
141	  channel_manager_.AbortAicpuChannelLocked(channel, &slot, &aicpu_resource);
142	}
