144	Status FabricMemAicpuTransferService::IssueCopyLocked(const std::shared_ptr<FabricMemChannel> &channel, AsyncSlot &slot,
145	                                                      const FabricMemTransferContext &context,
146	                                                      std::vector<TransferOpDesc> &op_descs,
147	                                                      TransferInvocation &invocation,
148	                                                      FabricMemAicpuRequestResource &aicpu_resource) {
149	  TemporaryRtContext ctx_guard(slot.ctx);
150	  HIXL_CHK_BOOL_RET_STATUS(!channel->disconnecting.load(std::memory_order_acquire), NOT_CONNECTED,
151	                           "Fabric mem channel:%s is disconnecting.", context.channel_id.c_str());
152	  HIXL_CHK_STATUS_RET(ResolveTransferAddrs(op_descs, context), "Resolve fabric mem addresses failed.");
153	  invocation.transfer_bytes = GetTransferBytes(op_descs);
154	  invocation.op_desc_count = static_cast<uint64_t>(op_descs.size());
155	  invocation.real_copy_start = std::chrono::steady_clock::now();
156	  return ProcessCopyWithAsync(slot, invocation.operation, op_descs, aicpu_resource, invocation.rtsq_timeout_ms);
157	}
