159	Status FabricMemAicpuTransferService::CompleteSyncTransferLocked(const std::shared_ptr<FabricMemChannel> &channel,
160	                                                                 AsyncSlot &slot,
161	                                                                 FabricMemAicpuRequestResource &aicpu_resource,
162	                                                                 const FabricMemTransferContext &context,
163	                                                                 const TransferInvocation &invocation) {
164	  HIXL_CHK_BOOL_RET_STATUS(!channel->disconnecting.load(std::memory_order_acquire), NOT_CONNECTED,
165	                           "Fabric mem channel is disconnecting.");
166	  {
167	    TemporaryRtContext ctx_guard(slot.ctx);
168	    HIXL_CHK_STATUS_RET(FabricMemAicpuDispatcher::CheckRequestStatus(aicpu_resource),
169	                        "FabricMem AICPU sync launch reported failure.");
170	    FabricMemAicpuDispatcher::ReleaseRequestResource(aicpu_resource);
171	  }
172	  const auto end = std::chrono::steady_clock::now();
173	  const auto real_copy_cost = GetDurationUs(invocation.real_copy_start, end);
174	  ReleaseBoundSlotLocked(channel, slot);
175	  const auto transfer_cost = GetDurationUs(invocation.transfer_start, end);
176	  UpdateStats(context.channel_id, context.statistic_channel_id, context.stat_info, transfer_cost, real_copy_cost,
177	              invocation.transfer_bytes, invocation.op_desc_count);
178	  HIXL_LOGD("Fabric mem AICPU transfer cost:%lu us, real copy:%lu us, channel:%s.", transfer_cost, real_copy_cost,
179	            context.channel_id.c_str());
180	  return SUCCESS;
181	}
