183	Status FabricMemAicpuTransferService::TransferSync(const std::string &remote_engine, TransferOp operation,
184	                                                   const std::vector<TransferOpDesc> &op_descs,
185	                                                   int32_t timeout_in_millis) {
186	  HIXL_CHK_BOOL_RET_STATUS(timeout_in_millis >= 0, PARAM_INVALID,
187	                           "Fabric mem transfer timeout must be non-negative, got:%d.", timeout_in_millis);
188	  const auto start = std::chrono::steady_clock::now();
189	  const uint64_t timeout_us = static_cast<uint64_t>(timeout_in_millis) * kMillisToMicros;
190	  std::shared_ptr<FabricMemChannel> channel;
191	  FabricMemTransferContext context;
192	  HIXL_CHK_STATUS_RET(PrepareChannelTransfer(remote_engine, channel, context), "Prepare fabric mem transfer failed.");
193	
194	  std::unique_lock<std::mutex> lock(channel->transfer_mu);
195	  AsyncSlot slot;
196	  HIXL_CHK_STATUS_RET(AcquireBoundSlotLocked(channel, slot, timeout_us, false),
197	                      "Begin fabric mem AICPU sync transfer failed.");
198	  FabricMemAicpuRequestResource aicpu_resource;
199	  HIXL_DISMISSABLE_GUARD(fail_guard, ([this, &channel, &slot, &aicpu_resource]() {
200	                           CleanupFailedTransferLocked(channel, slot, aicpu_resource);
201	                         }));
202	  auto op_descs_copy = op_descs;
203	  TransferInvocation invocation;
204	  invocation.operation = operation;
205	  invocation.transfer_start = start;
206	  // Kernel treats timeout_ms==0 as "use async default (60s)". Sync must never pass 0 when the
207	  // caller budget is already exhausted (or truncated below 1ms); fail with TIMEOUT instead.
208	  const auto elapsed_us = GetDurationUs(start, std::chrono::steady_clock::now());
209	  HIXL_CHK_BOOL_RET_STATUS(elapsed_us < timeout_us, TIMEOUT, "Fabric mem AICPU transfer timeout.");
210	  const uint64_t remaining_ms = (timeout_us - elapsed_us) / kMillisToMicros;
211	  HIXL_CHK_BOOL_RET_STATUS(remaining_ms > 0U, TIMEOUT, "Fabric mem AICPU transfer timeout.");
212	  invocation.rtsq_timeout_ms = static_cast<uint32_t>(remaining_ms);
213	  HIXL_CHK_STATUS_RET(IssueCopyLocked(channel, slot, context, op_descs_copy, invocation, aicpu_resource),
214	                      "Fabric mem AICPU sync copy failed.");
215	  HIXL_CHK_STATUS_RET(WaitControlStreamsWithTimeout(slot, start, timeout_us),
216	                      "Wait fabric mem AICPU sync streams failed.");
217	  HIXL_CHK_STATUS_RET(CompleteSyncTransferLocked(channel, slot, aicpu_resource, context, invocation),
218	                      "Complete fabric mem AICPU sync transfer failed.");
219	  HIXL_DISMISS_GUARD(fail_guard);
220	  return SUCCESS;
221	}
222	
223	Status FabricMemAicpuTransferService::TransferAsync(const std::string &remote_engine, TransferOp operation,
224	                                                    const std::vector<TransferOpDesc> &op_descs, TransferReq &req) {
225	  const uint64_t req_id = next_req_id_.fetch_add(1U, std::memory_order_relaxed);
226	  req = reinterpret_cast<TransferReq>(static_cast<uintptr_t>(req_id));
227	  const uint64_t prof_start_time = HixlProfilingReporter::GetSysCycleTime();
228	  const auto start = std::chrono::steady_clock::now();
229	  std::shared_ptr<FabricMemChannel> channel;
230	  FabricMemTransferContext context;
231	  HIXL_CHK_STATUS_RET(PrepareChannelTransfer(remote_engine, channel, context), "Prepare fabric mem transfer failed.");
232	
233	  std::unique_lock<std::mutex> lock(channel->transfer_mu);
234	  AsyncSlot slot;
235	  HIXL_CHK_STATUS_RET(AcquireBoundSlotLocked(channel, slot, 0U, true), "Begin fabric mem AICPU async transfer failed.");
236	  FabricMemAicpuRequestResource aicpu_resource;
237	  HIXL_DISMISSABLE_GUARD(fail_guard, ([this, &channel, &slot, &aicpu_resource]() {
238	                           CleanupFailedTransferLocked(channel, slot, aicpu_resource);
239	                         }));
240	  auto op_descs_copy = op_descs;
241	  TransferInvocation invocation;
242	  invocation.operation = operation;
243	  invocation.req_id = req_id;
244	  invocation.prof_start_time = prof_start_time;
245	  invocation.transfer_start = start;
246	  HIXL_CHK_STATUS_RET(IssueCopyLocked(channel, slot, context, op_descs_copy, invocation, aicpu_resource),
247	                      "Fabric mem AICPU async copy failed.");
248	  HIXL_CHK_STATUS_RET(AllocateTransferHostFlags(slot), "Allocate fabric mem AICPU async host flags failed.");
249	  {
250	    TemporaryRtContext ctx_guard(slot.ctx);
251	    HIXL_CHK_STATUS_RET(AppendHostFlagCopies(slot), "Failed to append fabric mem host flag copies.");
252	  }
253	  HIXL_CHK_BOOL_RET_STATUS(!channel->disconnecting.load(std::memory_order_acquire), NOT_CONNECTED,
254	                           "Fabric mem channel:%s is disconnecting.", context.channel_id.c_str());
255	  RegisterAsyncTransferRecord(req_id, channel, context, invocation, slot, aicpu_resource);
256	  HIXL_DISMISS_GUARD(fail_guard);
257	  HIXL_LOGD("Fabric mem AICPU async transfer submitted, channel:%s, req:%lu, cost:%lu us.", context.channel_id.c_str(),
258	            req_id, GetDurationUs(start, std::chrono::steady_clock::now()));
259	  return SUCCESS;
260	}
261	
262	void FabricMemAicpuTransferService::RegisterAsyncTransferRecord(uint64_t req_id,
263	                                                                const std::shared_ptr<FabricMemChannel> &channel,
264	                                                                const FabricMemTransferContext &context,
265	                                                                const TransferInvocation &invocation, AsyncSlot &slot,
266	                                                                FabricMemAicpuRequestResource &aicpu_resource) {
267	  AsyncRecord record;
268	  record.slot = std::move(slot);
269	  record.aicpu_resource = std::move(aicpu_resource);
270	  record.transfer_start = invocation.transfer_start;
271	  record.real_copy_start = invocation.real_copy_start;
272	  record.transfer_bytes = invocation.transfer_bytes;
273	  record.op_desc_count = invocation.op_desc_count;
274	  record.channel_id = context.channel_id;
275	  record.statistic_channel_id = context.statistic_channel_id;
276	  record.stat_info = context.stat_info;
277	  record.op_type = invocation.operation;
278	  record.prof_start_time = invocation.prof_start_time;
279	  {
280	    std::lock_guard<std::mutex> reg(channel->records_mutex);
281	    channel->async_records[req_id] = std::move(record);
282	  }
283	  channel_manager_.AddReqRoute(req_id, channel);
284	}
285	
286	Status FabricMemAicpuTransferService::GetTransferStatus(const TransferReq &req, TransferStatus &status,
287	                                                        AsyncTransferPollInfo *info) {
288	  const uint64_t req_id = reinterpret_cast<uintptr_t>(req);
289	  std::shared_ptr<FabricMemChannel> channel;
290	  HIXL_CHK_BOOL_RET_STATUS(channel_manager_.FindChannelByReq(req_id, channel) == SUCCESS, PARAM_INVALID,
291	                           "Fabric mem request:%lu not found.", req_id);
292	  std::lock_guard<std::mutex> transfer_lock(channel->transfer_mu);
293	
294	  AsyncRecord async_record;
295	  bool host_flags_done = false;
296	  {
297	    std::lock_guard<std::mutex> lock(channel->records_mutex);
298	    const auto it = channel->async_records.find(req_id);
299	    HIXL_CHK_BOOL_RET_STATUS(it != channel->async_records.end(), PARAM_INVALID, "Fabric mem request:%lu not found.",
300	                             req_id);
301	    host_flags_done = AllHostFlagsDone(it->second.slot);
302	    if (!host_flags_done) {
303	      TemporaryRtContext ctx_guard(it->second.slot.ctx);
304	      if (QueryAsyncSlotStreams(it->second.slot) != AsyncStreamQueryResult::kFailed) {
305	        status = TransferStatus::WAITING;
306	        return SUCCESS;
307	      }
308	    }
309	    async_record = std::move(it->second);
310	    (void)channel->async_records.erase(it);
311	  }
312	
313	  Status ret = SUCCESS;
314	  if (host_flags_done) {
315	    ret = CompleteAsyncTransferAndUpdateStats(req_id, channel, async_record, status);
316	  } else {
317	    ret = HandleAsyncStreamQueryFailure(req_id, channel, async_record, status);
318	  }
319	  if (ret != SUCCESS) {
320	    return ret;
321	  }
322	  FillPollInfo(async_record, info);
323	  channel_manager_.RemoveReqRoute(req_id);
324	  return ret;
325	}
326	
327	Status FabricMemAicpuTransferService::HandleAsyncStreamQueryFailure(uint64_t req_id,
328	                                                                    const std::shared_ptr<FabricMemChannel> &channel,
329	                                                                    AsyncRecord &async_record, TransferStatus &status) {
330	  CleanupFailedTransferLocked(channel, async_record.slot, async_record.aicpu_resource);
331	  status = TransferStatus::FAILED;
332	  HIXL_LOGE(FAILED, "Fabric mem AICPU async transfer failed on stream query, req:%lu.", req_id);
333	  return SUCCESS;
334	}
335	
336	Status FabricMemAicpuTransferService::CompleteAsyncTransferAndUpdateStats(
337	    uint64_t req_id, const std::shared_ptr<FabricMemChannel> &channel, AsyncRecord &async_record,
338	    TransferStatus &status) {
339	  Status launch_status = SUCCESS;
340	  {
341	    TemporaryRtContext ctx_guard(async_record.slot.ctx);
342	    launch_status = FabricMemAicpuDispatcher::CheckRequestStatus(async_record.aicpu_resource);
343	    if (launch_status == SUCCESS) {
344	      FabricMemAicpuDispatcher::ReleaseRequestResource(async_record.aicpu_resource);
345	    }
346	  }
347	  if (launch_status != SUCCESS) {
348	    // The kernel reported a submit error; let the abort flow free the descriptors it may still hold.
349	    CleanupFailedTransferLocked(channel, async_record.slot, async_record.aicpu_resource);
350	    status = TransferStatus::FAILED;
351	    HIXL_LOGE(launch_status, "FabricMem AICPU async launch reported failure, req:%lu.", req_id);
352	    return SUCCESS;
353	  }
354	  ReleaseBoundSlotLocked(channel, async_record.slot);
355	  const auto end = std::chrono::steady_clock::now();
356	  const auto real_copy_cost = GetDurationUs(async_record.real_copy_start, end);
357	  const auto transfer_cost = GetDurationUs(async_record.transfer_start, end);
358	  UpdateStats(async_record.channel_id, async_record.statistic_channel_id, async_record.stat_info, transfer_cost,
359	              real_copy_cost, async_record.transfer_bytes, async_record.op_desc_count);
360	  status = TransferStatus::COMPLETED;
361	  HIXL_LOGD("Fabric mem AICPU async transfer completed, channel:%s, req:%lu, cost:%lu us, real copy:%lu us.",
362	            async_record.channel_id.c_str(), req_id, transfer_cost, real_copy_cost);
363	  return SUCCESS;
364	}
365	
366	void FabricMemAicpuTransferService::CleanupAsyncTransfer(const TransferReq &req) {
367	  const uint64_t req_id = reinterpret_cast<uintptr_t>(req);
368	  std::shared_ptr<FabricMemChannel> channel;
369	  if (channel_manager_.FindChannelByReq(req_id, channel) != SUCCESS) {
370	    return;
371	  }
372	  std::lock_guard<std::mutex> transfer_lock(channel->transfer_mu);
373	  AsyncRecord async_record;
374	  bool found = false;
375	  {
376	    std::lock_guard<std::mutex> lock(channel->records_mutex);
377	    const auto it = channel->async_records.find(req_id);
378	    if (it != channel->async_records.end()) {
379	      async_record = std::move(it->second);
380	      (void)channel->async_records.erase(it);
381	      found = true;
382	    }
383	  }
384	  if (found) {
385	    // A submitted request cannot be cancelled in isolation once it shares the channel's control
386	    // stream, so this tears the channel down the same way a failure does.
387	    CleanupFailedTransferLocked(channel, async_record.slot, async_record.aicpu_resource);
388	  }
389	  channel_manager_.RemoveReqRoute(req_id);
390	}
391	
392	Status FabricMemAicpuTransferService::ProcessCopyWithAsync(AsyncSlot &slot, TransferOp operation,
393	                                                           const std::vector<TransferOpDesc> &op_descs,
394	                                                           FabricMemAicpuRequestResource &aicpu_resource,
395	                                                           uint32_t rtsq_timeout_ms) {
396	  HIXL_CHK_BOOL_RET_STATUS(!slot.streams.empty(), PARAM_INVALID, "Fabric mem copy streams cannot be empty.");
397	  HIXL_CHK_BOOL_RET_STATUS(aicpu_dispatcher_.IsInitialized(), FAILED, "FabricMem AICPU dispatcher is not initialized.");
398	  HIXL_CHK_BOOL_RET_STATUS(slot.has_aicpu_unfold, FAILED, "FabricMem AICPU RTSQ worker streams are not ready.");
399	  // UT and direct callers may skip AcquireBoundSlotLocked; ensure TransferContext exists before Submit.
400	  if (slot.transfer_ctx_key == 0U) {
401	    HIXL_CHK_STATUS_RET(aicpu_dispatcher_.AddTransferContext(slot),
402	                        "Register FabricMem AICPU transfer context failed.");
403	  }
404	  return aicpu_dispatcher_.Submit(slot, operation, op_descs, aicpu_resource, rtsq_timeout_ms);
405	}
406	}  // namespace hixl
