26	
27	namespace hixl {
28	namespace {
29	constexpr const char *kHixlFabricMemBatchRead = "HixlFabricMemBatchRead";
30	constexpr const char *kHixlFabricMemBatchWrite = "HixlFabricMemBatchWrite";
31	constexpr const char *kHixlSyncTransferContext = "HixlSyncTransferContext";
32	constexpr uint32_t kFabricMemKernelBlockDim = 1U;
33	constexpr uint32_t kMaxDescriptorsPerKernelLaunch = 128U;
34	constexpr uint32_t kDefaultNotifyWaitTimeoutSec = 60U;
35	constexpr uint32_t kMillisPerSecond = 1000U;
36	constexpr uint64_t kMaxSdmaTransferBytes = std::numeric_limits<uint32_t>::max();
37	constexpr uint32_t kSyncContextKernelTimeoutMs = 10U * 1000U;
38	constexpr uint32_t kSyncContextRetryTimeoutMs = 30U * 1000U;
39	constexpr uint32_t kSyncContextRetryIntervalMs = 100U;
40	
41	Status CountKernelLaunches(size_t desc_count, size_t &launch_count) {
42	  HIXL_CHK_BOOL_RET_STATUS(desc_count > 0U, PARAM_INVALID, "FabricMem AICPU launch count inputs are invalid.");
43	  launch_count = (desc_count + kMaxDescriptorsPerKernelLaunch - 1U) / kMaxDescriptorsPerKernelLaunch;
44	  return SUCCESS;
45	}
46	
47	Status BuildDeviceDescriptors(TransferOp operation, const std::vector<TransferOpDesc> &op_descs,
48	                              std::vector<FabricMemAicpuTransferDesc> &device_descs,
49	                              FabricMemAicpuTransferDirection &direction) {
50	  HIXL_CHK_BOOL_RET_STATUS(!op_descs.empty(), PARAM_INVALID, "FabricMem AICPU transfer descriptors cannot be empty.");
51	  if (operation == TransferOp::READ) {
52	    direction = FabricMemAicpuTransferDirection::kRead;
53	  } else if (operation == TransferOp::WRITE) {
54	    direction = FabricMemAicpuTransferDirection::kWrite;
55	  } else {
56	    HIXL_LOGE(PARAM_INVALID, "Invalid FabricMem AICPU transfer operation.");
57	    return PARAM_INVALID;
58	  }
59	  device_descs.clear();
60	  device_descs.reserve(op_descs.size());
61	  for (const auto &op_desc : op_descs) {
62	    HIXL_CHK_BOOL_RET_STATUS(op_desc.local_addr != 0U && op_desc.remote_addr != 0U && op_desc.len > 0U, PARAM_INVALID,
63	                             "Invalid FabricMem AICPU transfer descriptor.");
64	    uint64_t local_addr = static_cast<uint64_t>(op_desc.local_addr);
65	    uint64_t remote_addr = static_cast<uint64_t>(op_desc.remote_addr);
66	    uint64_t remaining = static_cast<uint64_t>(op_desc.len);
67	    HIXL_CHK_BOOL_RET_STATUS(remaining <= std::numeric_limits<uint64_t>::max() - local_addr &&
68	                                 remaining <= std::numeric_limits<uint64_t>::max() - remote_addr,
69	                             PARAM_INVALID, "FabricMem AICPU transfer descriptor address range overflows.");
70	    // Split here rather than letting the kernel do it, so one device descriptor is exactly one SDMA
71	    // SQE. That is what lets the host count the RTSQ entries a launch will occupy and throttle with
72	    // NotifyRecord waits before the queue can fill up.
73	    while (remaining > 0U) {
74	      const uint64_t block_size = std::min(remaining, kMaxSdmaTransferBytes);
75	      FabricMemAicpuTransferDesc device_desc;
76	      if (direction == FabricMemAicpuTransferDirection::kRead) {
77	        device_desc.src_addr = remote_addr;
78	        device_desc.dst_addr = local_addr;
79	      } else {
80	        device_desc.src_addr = local_addr;
81	        device_desc.dst_addr = remote_addr;
82	      }
83	      device_desc.length = block_size;
84	      device_descs.emplace_back(device_desc);
85	      local_addr += block_size;
86	      remote_addr += block_size;
87	      remaining -= block_size;
88	    }
89	  }
90	  HIXL_CHK_BOOL_RET_STATUS(
91	      device_descs.size() <= std::numeric_limits<size_t>::max() / sizeof(FabricMemAicpuTransferDesc), PARAM_INVALID,
92	      "FabricMem AICPU descriptor buffer size overflows.");
93	  return SUCCESS;
94	}
