101	Status FabricMemAicpuDispatcher::InitializeRtsqDevice() {
102	  // The host passes the physical device id to the AICPU kernel, which converts it
103	  // to the driver-local id via drvGetLocalDevIDByHostDevID before calling halSqCqQuery.
104	  int32_t physical_device_id = -1;
105	  if (aclrtGetPhyDevIdByLogicDevId(device_id_, &physical_device_id) != ACL_SUCCESS || physical_device_id < 0) {
106	    HIXL_LOGW("FabricMem AICPU unfold cannot resolve physical device id for logical device:%d.", device_id_);
107	    return UNSUPPORTED;
108	  }
109	  rtsq_device_id_ = static_cast<uint32_t>(physical_device_id);
110	  return SUCCESS;
111	}
112	
113	Status FabricMemAicpuDispatcher::Initialize(int32_t device_id) {
114	  HIXL_CHK_BOOL_RET_STATUS(device_id >= 0, PARAM_INVALID, "FabricMem AICPU device id must be non-negative.");
115	  std::lock_guard<std::mutex> lock(lifecycle_mutex_);
116	  if (initialized_.load(std::memory_order_acquire)) {
117	    if (device_id_ == device_id) {
118	      return SUCCESS;
119	    }
120	    HIXL_LOGE(PARAM_INVALID,
121	              "FabricMem AICPU dispatcher already initialized on device:%d, reject re-init on device:%d.", device_id_,
122	              device_id);
123	    return PARAM_INVALID;
124	  }
125	  device_id_ = device_id;
126	  if (InitializeRtsqDevice() != SUCCESS) {
127	    device_id_ = -1;
128	    return UNSUPPORTED;
129	  }
130	
131	  std::vector<aclrtFuncHandle> handles;
132	  const Status load_status = LoadDeviceKernelFunctions(
133	      {kHixlFabricMemBatchRead, kHixlFabricMemBatchWrite, kHixlSyncTransferContext}, binary_handle_, handles);
134	  if (load_status != SUCCESS || handles.size() != 3U || handles[0U] == nullptr || handles[1U] == nullptr ||
135	      handles[2U] == nullptr) {
136	    HIXL_LOGW("FabricMem AICPU unfold is unavailable: kernel binary or A3 RTSQ runtime is not installed.");
137	    if (binary_handle_ != nullptr) {
138	      HIXL_CHK_ACL(aclrtBinaryUnLoad(binary_handle_), "Unload FabricMem AICPU kernel failed.");
139	      binary_handle_ = nullptr;
140	    }
141	    device_id_ = -1;
142	    rtsq_device_id_ = 0U;
143	    return UNSUPPORTED;
144	  }
145	  batch_read_ = handles[0U];
146	  batch_write_ = handles[1U];
147	  sync_transfer_context_ = handles[2U];
148	  initialized_.store(true, std::memory_order_release);
149	  HIXL_LOGI("FabricMem AICPU dispatcher initialized, device:%d.", device_id_);
150	  return SUCCESS;
151	}
