153	void FabricMemAicpuDispatcher::Finalize() {
154	  std::lock_guard<std::mutex> lock(lifecycle_mutex_);
155	  initialized_.store(false, std::memory_order_release);
156	  if (binary_handle_ != nullptr) {
157	    HIXL_CHK_ACL(aclrtBinaryUnLoad(binary_handle_), "Unload FabricMem AICPU kernel failed.");
158	  }
159	  binary_handle_ = nullptr;
160	  batch_read_ = nullptr;
161	  batch_write_ = nullptr;
162	  sync_transfer_context_ = nullptr;
163	  device_id_ = -1;
164	  rtsq_device_id_ = 0U;
165	  std::lock_guard<std::mutex> task_id_lock(task_id_mutex_);
166	  rtsq_next_task_ids_.clear();
167	}
