220	Status FabricMemAicpuDispatcher::BuildRtsqKernelParam(aclrtStream worker_stream, uint32_t task_count,
221	                                                      FabricMemAicpuKernelParam &param) {
222	  HIXL_CHK_BOOL_RET_STATUS(worker_stream != nullptr && task_count > 0U, PARAM_INVALID,
223	                           "FabricMem AICPU RTSQ worker stream or task count is invalid.");
224	  int32_t stream_id = -1;
225	  HIXL_CHK_ACL_RET(aclrtStreamGetId(worker_stream, &stream_id), "Get FabricMem AICPU RTSQ stream id failed.");
226	  HIXL_CHK_BOOL_RET_STATUS(stream_id >= 0 && stream_id <= std::numeric_limits<uint16_t>::max(), UNSUPPORTED,
227	                           "FabricMem AICPU RTSQ stream id is outside the A3 SQE ABI range.");
228	  uint32_t sq_id = 0U;
229	  HIXL_CHK_BOOL_RET_STATUS(rtStreamGetSqid(reinterpret_cast<rtStream_t>(worker_stream), &sq_id) == RT_ERROR_NONE,
230	                           UNSUPPORTED, "Get FabricMem AICPU RTSQ queue id failed.");
231	  uint32_t cq_id = 0U;
232	  uint32_t logic_cq_id = 0U;
233	  HIXL_CHK_BOOL_RET_STATUS(
234	      rtStreamGetCqid(reinterpret_cast<rtStream_t>(worker_stream), &cq_id, &logic_cq_id) == RT_ERROR_NONE, UNSUPPORTED,
235	      "Get FabricMem AICPU RTSQ completion queue ids failed.");
236	  (void)cq_id;
237	  param.device_id = rtsq_device_id_;
238	  param.rtsq_id = sq_id;
239	  param.rtsq_stream_id = static_cast<uint32_t>(stream_id);
240	  param.rtsq_logic_cq_id = logic_cq_id;
241	  // SQE task_id is uint16 on A3; keep a host-side counter and truncate on use.
242	  param.rtsq_task_id = static_cast<uint16_t>(ReserveRtsqTaskIds(sq_id, task_count));
243	  return SUCCESS;
244	}
