246	uint32_t FabricMemAicpuDispatcher::ReserveRtsqTaskIds(uint32_t sq_id, uint32_t task_count) {
247	  std::lock_guard<std::mutex> lock(task_id_mutex_);
248	  const uint32_t first_task_id = rtsq_next_task_ids_[sq_id];
249	  rtsq_next_task_ids_[sq_id] = first_task_id + task_count;
250	  return first_task_id;
251	}
