253	Status FabricMemAicpuDispatcher::LaunchSyncContextKernel(const std::vector<HixlTransferContextSyncEntry> &entries,
254	                                                         std::vector<uint32_t> &states) const {
255	  HIXL_CHK_BOOL_RET_STATUS(sync_transfer_context_ != nullptr, FAILED,
256	                           "FabricMem AICPU sync transfer context func is null.");
257	  HIXL_CHK_BOOL_RET_STATUS(!entries.empty(), PARAM_INVALID, "FabricMem AICPU sync context entries is empty.");
258	  const size_t entry_bytes = entries.size() * sizeof(HixlTransferContextSyncEntry);
259	  void *dev_entries = nullptr;
260	  HIXL_CHK_ACL_RET(aclrtMalloc(&dev_entries, entry_bytes, ACL_MEM_MALLOC_NORMAL_ONLY),
261	                   "Allocate FabricMem AICPU sync context entries failed.");
262	  HIXL_DISMISSABLE_GUARD(free_dev_entries, ([dev_entries]() {
263	                           HIXL_CHK_ACL(aclrtFree(dev_entries), "Free FabricMem AICPU sync context entries failed.");
264	                         }));
265	  states.assign(entries.size(), TRANSFER_THREAD_STATE_DELETED);
266	  const size_t state_bytes = states.size() * sizeof(uint32_t);
267	  void *dev_states = nullptr;
268	  HIXL_CHK_ACL_RET(aclrtMalloc(&dev_states, state_bytes, ACL_MEM_MALLOC_NORMAL_ONLY),
269	                   "Allocate FabricMem AICPU sync context states failed.");
270	  HIXL_DISMISSABLE_GUARD(free_dev_states, ([dev_states]() {
271	                           HIXL_CHK_ACL(aclrtFree(dev_states), "Free FabricMem AICPU sync context states failed.");
272	                         }));
273	  HIXL_CHK_ACL_RET(aclrtMemcpy(dev_entries, entry_bytes, entries.data(), entry_bytes, ACL_MEMCPY_HOST_TO_DEVICE),
274	                   "Upload FabricMem AICPU sync context entries failed.");
275	  HixlTransferContextSyncParam param{};
276	  param.entry_list_addr = PtrToValue(dev_entries);
277	  param.state_list_addr = PtrToValue(dev_states);
278	  param.entry_num = static_cast<uint32_t>(entries.size());
279	  void *dev_args = nullptr;
280	  HIXL_CHK_ACL_RET(aclrtMalloc(&dev_args, sizeof(param), ACL_MEM_MALLOC_NORMAL_ONLY),
281	                   "Allocate HixlSyncTransferContext args failed.");
282	  HIXL_DISMISSABLE_GUARD(free_dev_args, ([dev_args]() {
283	                           HIXL_CHK_ACL(aclrtFree(dev_args), "Free HixlSyncTransferContext args failed.");
284	                         }));
285	  HIXL_CHK_ACL_RET(aclrtMemcpy(dev_args, sizeof(param), &param, sizeof(param), ACL_MEMCPY_HOST_TO_DEVICE),
286	                   "Upload HixlSyncTransferContext param failed.");
287	  aclrtStream stream = nullptr;
288	  HIXL_CHK_ACL_RET(aclrtCtxGetCurrentDefaultStream(&stream), "Get default stream for HixlSyncTransferContext failed.");
289	  HIXL_CHK_ACL_RET(
290	      aclrtLaunchKernelV2(sync_transfer_context_, kFabricMemKernelBlockDim, dev_args, sizeof(param), nullptr, stream),
291	      "Launch HixlSyncTransferContext failed.");
292	  HIXL_CHK_ACL_RET(aclrtSynchronizeStreamWithTimeout(stream, static_cast<int32_t>(kSyncContextKernelTimeoutMs)),
293	                   "Synchronize HixlSyncTransferContext failed.");
294	  HIXL_CHK_ACL_RET(aclrtMemcpy(states.data(), state_bytes, dev_states, state_bytes, ACL_MEMCPY_DEVICE_TO_HOST),
295	                   "Download FabricMem AICPU sync context states failed.");
296	  return SUCCESS;
297	}
298	
299	Status FabricMemAicpuDispatcher::CollectRetrySyncEntries(
300	    const std::vector<HixlTransferContextSyncEntry> &entries, const std::vector<uint32_t> &states, uint32_t op,
301	    uint32_t expect_state, std::vector<HixlTransferContextSyncEntry> &retry_entries) const {
302	  HIXL_CHK_BOOL_RET_STATUS(entries.size() == states.size(), FAILED,
303	                           "FabricMem AICPU sync context state size mismatch, entries=%zu states=%zu", entries.size(),
304	                           states.size());
305	  for (size_t i = 0U; i < entries.size(); ++i) {
306	    const uint32_t state = states[i];
307	    if (state == expect_state) {
308	      continue;
309	    }
310	    HIXL_CHK_BOOL_RET_STATUS(state == TRANSFER_THREAD_STATE_DELETING, FAILED,
311	                             "FabricMem AICPU unexpected transfer context state:%u, key:%lu, op:%u, expect:%u", state,
312	                             static_cast<uint64_t>(entries[i].thread), op, expect_state);
313	    HIXL_LOGD("FabricMem AICPU delete transfer context busy (try_lock failed), will retry. key=%lu op=%u",
314	              static_cast<uint64_t>(entries[i].thread), op);
315	    HixlTransferContextSyncEntry entry{};
316	    entry.thread = entries[i].thread;
317	    entry.op = op;
318	    retry_entries.push_back(entry);
319	  }
320	  return SUCCESS;
321	}
322	
323	Status FabricMemAicpuDispatcher::HandleSyncContextTimeout(const std::vector<HixlTransferContextSyncEntry> &pending,
324	                                                          const std::vector<uint32_t> &states, uint32_t op) const {
325	  HIXL_CHK_BOOL_RET_STATUS(op == TRANSFER_CONTEXT_OP_DELETE, TIMEOUT,
326	                           "FabricMem AICPU sync transfer context timeout, pending:%zu, op:%u, device_id:%d",
327	                           pending.size(), op, device_id_);
328	  for (size_t i = 0U; i < pending.size(); ++i) {
329	    const uint32_t state = (i < states.size()) ? states[i] : TRANSFER_THREAD_STATE_DELETING;
330	    HIXL_EVENT(
331	        "FabricMem AICPU delete transfer context timeout after %u ms, force cleanup. key=%lu state=%u device_id=%d",
332	        kSyncContextRetryTimeoutMs, static_cast<uint64_t>(pending[i].thread), state, device_id_);
333	  }
334	  return SUCCESS;
335	}
336	
337	Status FabricMemAicpuDispatcher::SyncTransferContext(ThreadHandle key, uint32_t op, uint32_t expect_state) const {
338	  if (key == 0U) {
339	    return SUCCESS;
340	  }
341	  HIXL_CHK_BOOL_RET_STATUS(sync_transfer_context_ != nullptr, FAILED,
342	                           "FabricMem AICPU sync transfer context func is null.");
343	  std::vector<HixlTransferContextSyncEntry> pending(1U);
344	  pending[0U].thread = key;
345	  pending[0U].op = op;
346	  const auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(kSyncContextRetryTimeoutMs);
347	  std::vector<uint32_t> pending_states;
348	  while (!pending.empty()) {
349	    std::vector<uint32_t> states;
350	    HIXL_CHK_STATUS_RET(LaunchSyncContextKernel(pending, states), "FabricMem AICPU launch sync context failed.");
351	    std::vector<HixlTransferContextSyncEntry> retry_entries;
352	    HIXL_CHK_STATUS_RET(CollectRetrySyncEntries(pending, states, op, expect_state, retry_entries),
353	                        "FabricMem AICPU collect sync context retries failed.");
354	    pending.swap(retry_entries);
355	    pending_states.swap(states);
356	    if (pending.empty()) {
357	      return SUCCESS;
358	    }
359	    if (std::chrono::steady_clock::now() >= deadline) {
360	      return HandleSyncContextTimeout(pending, pending_states, op);
361	    }
362	    std::this_thread::sleep_for(std::chrono::milliseconds(kSyncContextRetryIntervalMs));
363	  }
364	  return SUCCESS;
365	}
