367	Status FabricMemAicpuDispatcher::AddTransferContext(AsyncSlot &slot) const {
368	  HIXL_CHK_BOOL_RET_STATUS(!slot.notifies.empty() && slot.notifies[0U] != nullptr, PARAM_INVALID,
369	                           "FabricMem AICPU slot notify is required for transfer context.");
370	  HIXL_CHK_BOOL_RET_STATUS(slot.ctx != nullptr, PARAM_INVALID, "FabricMem AICPU slot context is null.");
371	  slot.transfer_ctx_key = static_cast<uint64_t>(reinterpret_cast<uintptr_t>(slot.notifies[0U]));
372	  HIXL_CHK_BOOL_RET_STATUS(IsInitialized(), FAILED, "FabricMem AICPU dispatcher is not initialized.");
373	  TemporaryRtContext ctx_guard(slot.ctx);
374	  return SyncTransferContext(static_cast<ThreadHandle>(slot.transfer_ctx_key), TRANSFER_CONTEXT_OP_ADD,
375	                             TRANSFER_THREAD_STATE_INITIALIZED);
376	}
