378	Status FabricMemAicpuDispatcher::DeleteTransferContext(const AsyncSlot &slot) const {
379	  if (slot.transfer_ctx_key == 0U || slot.ctx == nullptr) {
380	    return SUCCESS;
381	  }
382	  // Runs on the aborting thread only, which may block here for up to the sync-context retry budget.
383	  // No dispatcher-wide lock is taken, so other channels keep submitting meanwhile.
384	  HIXL_CHK_BOOL_RET_STATUS(IsInitialized(), FAILED, "FabricMem AICPU dispatcher is not initialized.");
385	  TemporaryRtContext ctx_guard(slot.ctx);
386	  return SyncTransferContext(static_cast<ThreadHandle>(slot.transfer_ctx_key), TRANSFER_CONTEXT_OP_DELETE,
387	                             TRANSFER_THREAD_STATE_DELETED);
388	}
