390	Status FabricMemAicpuDispatcher::LaunchOneDescriptorBatch(const AsyncSlot &slot, aclrtFuncHandle function,
391	                                                          FabricMemAicpuTransferDirection direction,
392	                                                          void *descriptor_buffer, void *status_buffer,
393	                                                          void *kernel_args_buffer, size_t begin, size_t count,
394	                                                          size_t total_descs, uint32_t rtsq_timeout_ms,
395	                                                          size_t &status_idx, size_t &tasks_since_notify) {
396	  // BuildDeviceDescriptors already split oversized transfers, so this batch is exactly `count` SDMA
397	  // SQEs plus an optional NotifyRecord.
398	  const size_t next_task_count = tasks_since_notify + count;
399	  const bool transfer_tail = begin + count == total_descs;
400	  const bool emit_notify = next_task_count >= kFabricMemMaxInFlightRtsqTasks || transfer_tail;
401	  FabricMemAicpuKernelParam param;
402	  param.desc_addr = static_cast<uint64_t>(reinterpret_cast<uintptr_t>(descriptor_buffer) +
403	                                          begin * sizeof(FabricMemAicpuTransferDesc));
404	  param.desc_count = static_cast<uint32_t>(count);
405	  param.direction = static_cast<uint32_t>(direction);
406	  param.timeout_ms = rtsq_timeout_ms;
407	  param.notify_id = slot.notify_ids[0U];
408	  param.emit_notify_record = emit_notify ? 1U : 0U;
409	  param.transfer_ctx_key = slot.transfer_ctx_key;
410	  if (status_buffer != nullptr) {
411	    param.status_addr =
412	        static_cast<uint64_t>(reinterpret_cast<uintptr_t>(status_buffer) + status_idx * sizeof(uint32_t));
413	  }
414	  const uint32_t rtsq_task_count = static_cast<uint32_t>(count) + (emit_notify ? 1U : 0U);
415	  HIXL_CHK_STATUS_RET(BuildRtsqKernelParam(slot.sdma_streams[0U], rtsq_task_count, param),
416	                      "Build FabricMem AICPU RTSQ kernel parameter failed.");
417	  void *dev_args = static_cast<uint8_t *>(kernel_args_buffer) + status_idx * sizeof(FabricMemAicpuKernelParam);
418	  HIXL_CHK_STATUS_RET(LaunchKernel(function, slot.streams[0U], param, dev_args),
419	                      "Launch FabricMem AICPU descriptor batch failed.");
420	  if (emit_notify) {
421	    const uint32_t wait_timeout_sec = rtsq_timeout_ms == 0U
422	                                          ? kDefaultNotifyWaitTimeoutSec
423	                                          : std::max(1U, (rtsq_timeout_ms / kMillisPerSecond) +
424	                                                             ((rtsq_timeout_ms % kMillisPerSecond) == 0U ? 0U : 1U));
425	    HIXL_CHK_ACL_RET(aclrtWaitAndResetNotify(slot.notifies[0U], slot.streams[0U], wait_timeout_sec),
426	                     "Enqueue FabricMem AICPU notify wait failed.");
427	    tasks_since_notify = 0U;
428	  } else {
429	    tasks_since_notify = next_task_count;
430	  }
431	  ++status_idx;
432	  return SUCCESS;
433	}
434	
435	Status FabricMemAicpuDispatcher::LaunchDescriptorBatches(const AsyncSlot &slot,
436	                                                         const std::vector<FabricMemAicpuTransferDesc> &descs,
437	                                                         FabricMemAicpuTransferDirection direction,
438	                                                         void *descriptor_buffer, void *status_buffer,
439	                                                         void *kernel_args_buffer, uint32_t rtsq_timeout_ms) {
440	  const aclrtFuncHandle function = direction == FabricMemAicpuTransferDirection::kRead ? batch_read_ : batch_write_;
441	  size_t status_idx = 0U;
442	  size_t begin = 0U;
443	  size_t tasks_since_notify = 0U;
444	  while (begin < descs.size()) {
445	    const size_t count = std::min(static_cast<size_t>(kMaxDescriptorsPerKernelLaunch), descs.size() - begin);
446	    HIXL_CHK_STATUS_RET(
447	        LaunchOneDescriptorBatch(slot, function, direction, descriptor_buffer, status_buffer, kernel_args_buffer, begin,
448	                                 count, descs.size(), rtsq_timeout_ms, status_idx, tasks_since_notify),
449	        "Launch FabricMem AICPU descriptor batch failed.");
450	    begin += count;
451	  }
452	  return SUCCESS;
453	}
454	
455	Status FabricMemAicpuDispatcher::Submit(const AsyncSlot &slot, TransferOp operation,
456	                                        const std::vector<TransferOpDesc> &op_descs,
457	                                        FabricMemAicpuRequestResource &resource, uint32_t rtsq_timeout_ms) {
458	  HIXL_CHK_BOOL_RET_STATUS(resource.descriptor_buffer == nullptr && resource.status_buffer == nullptr, PARAM_INVALID,
459	                           "FabricMem AICPU descriptor resource is already in use.");
460	  // AICPU unfold is fixed to a single control/worker/notify triple.
461	  HIXL_CHK_BOOL_RET_STATUS(slot.streams.size() == 1U && slot.sdma_streams.size() == 1U && slot.notifies.size() == 1U &&
462	                               slot.notify_ids.size() == 1U,
463	                           PARAM_INVALID, "FabricMem AICPU unfold requires exactly one stream/notify pair.");
464	  HIXL_CHK_BOOL_RET_STATUS(slot.transfer_ctx_key != 0U, PARAM_INVALID,
465	                           "FabricMem AICPU transfer context key is not registered.");
466	
467	  std::vector<FabricMemAicpuTransferDesc> device_descs;
468	  FabricMemAicpuTransferDirection direction = FabricMemAicpuTransferDirection::kRead;
469	  HIXL_CHK_STATUS_RET(BuildDeviceDescriptors(operation, op_descs, device_descs, direction),
470	                      "Build FabricMem AICPU device descriptors failed.");
471	  size_t launch_count = 0U;
472	  HIXL_CHK_STATUS_RET(CountKernelLaunches(device_descs.size(), launch_count),
473	                      "Count FabricMem AICPU kernel launches failed.");
474	
475	  HIXL_CHK_BOOL_RET_STATUS(IsInitialized(), FAILED, "FabricMem AICPU dispatcher is not initialized.");
476	  const size_t descriptor_bytes = device_descs.size() * sizeof(FabricMemAicpuTransferDesc);
477	  const size_t status_bytes = launch_count * sizeof(uint32_t);
478	  HIXL_CHK_ACL_RET(aclrtMalloc(&resource.descriptor_buffer, descriptor_bytes, ACL_MEM_MALLOC_NORMAL_ONLY),
479	                   "Allocate FabricMem AICPU descriptor buffer failed.");
480	  resource.descriptor_buffer_size = descriptor_bytes;
481	  // Free only on pre-launch failures. Once any kernel may have been enqueued the buffer is owned by
482	  // the device: the caller keeps it and hands it to FabricMemSlotPool::AbortSlot, which frees it
483	  // after the kernel has exited.
484	  HIXL_DISMISSABLE_GUARD(buffer_guard, ([&resource]() { ReleaseRequestResource(resource); }));
485	  HIXL_CHK_ACL_RET(aclrtMalloc(&resource.status_buffer, status_bytes, ACL_MEM_MALLOC_NORMAL_ONLY),
486	                   "Allocate FabricMem AICPU status buffer failed.");
487	  resource.status_count = launch_count;
488	  const size_t kernel_args_bytes = launch_count * sizeof(FabricMemAicpuKernelParam);
489	  HIXL_CHK_ACL_RET(aclrtMalloc(&resource.kernel_args_buffer, kernel_args_bytes, ACL_MEM_MALLOC_NORMAL_ONLY),
490	                   "Allocate FabricMem AICPU kernel args buffer failed.");
491	  resource.kernel_args_count = launch_count;
492	  std::vector<uint32_t> zero_status(launch_count, 0U);
493	  HIXL_CHK_ACL_RET(
494	      aclrtMemcpy(resource.status_buffer, status_bytes, zero_status.data(), status_bytes, ACL_MEMCPY_HOST_TO_DEVICE),
495	      "Initialize FabricMem AICPU status buffer failed.");
496	  HIXL_CHK_ACL_RET(aclrtMemcpy(resource.descriptor_buffer, descriptor_bytes, device_descs.data(), descriptor_bytes,
497	                               ACL_MEMCPY_HOST_TO_DEVICE),
498	                   "Upload FabricMem AICPU descriptors failed.");
499	  const Status launch_status =
500	      LaunchDescriptorBatches(slot, device_descs, direction, resource.descriptor_buffer, resource.status_buffer,
501	                              resource.kernel_args_buffer, rtsq_timeout_ms);
502	  HIXL_DISMISS_GUARD(buffer_guard);
503	  return launch_status;
504	}
505	
506	}  // namespace hixl
